package com.foodplan.domain

import org.junit.Assert.*
import org.junit.Test

/** Third 20-candidate YAR-6 method intake: 9 documented, 11 rejected. */
class M2PublishedMethodBulkThird20261025Test {
    private data class Frozen(
        val id: String, val recipeSha: String, val excerptSha: String,
        val kcal: Double, val protein: Double, val fat: Double, val carbs: Double
    )

    // Externally frozen literals, not generated by the runtime recipe planner.
    private val admitted = listOf(
        Frozen("cur_turkey_buckwheat", "80ec410b79e44a4618d203562f361aab93596cee5a54dd177cba213ccb4003f1", "8cd22ff6b17039ee9664fd7b6f3e306431681d3bb1a97496313fb0f86bef79ba", 647.42, 54.4105, 13.3535, 82.0415),
        Frozen("cur_baked_potato_chickpeas", "4930f844e2237b9a42382a8762f836a22d0fe7786ca1150233ef33b32981f28f", "b88005c19ba45fa2a2a29477a3d35c9a82ac98a9038399f494ca609de9841d54", 648.94, 21.259, 16.603, 108.932),
        Frozen("cur_baked_apple_oats", "31db426d327d1a19e3d0a17c5c661cd3e96360d3d69af113ee0dbd209239f72d", "420ca4e29245f236118f0aa2520e0a2243b7dc835485eed5312c0ea104a05e8a", 388.4, 11.684, 7.876, 71.671),
        Frozen("cur_turkey_lentil_stew", "e156d988f982d27129f56f030f74f31f91547d3cab46210788e7fb772e4c94ae", "c62a72defb5023909a954ba67317da7936a37e4a79e02a1da55a1c0bea151d18", 670.9, 63.8045, 14.48, 74.9125),
        Frozen("cur_beef_cabbage_rolls", "01f0060e0327022567c7f4db42c304644a4b9127671b0b0efce874580fe76225", "d2a12a23a14c40166abf380a6e05430cef28ae21838f44818ed2f219a6fb5578", 889.73125, 55.1998875, 27.75125, 105.3321125),
        Frozen("cur_chicken_potato_gratin", "a135971a88790b4c7d79c1a90be1ac044197d18861a40d5aab908c33e0ab6976", "50217b719d75774396fa058565ac417bdf65a9175a698a603ef06883cf32a1a9", 1020.1463, 81.28475, 41.2743, 87.045),
        Frozen("cur_cabbage_mushroom_dumplings", "c93eb7838c293c0ffc0f65bf67d2d0e4d3c7d8da67c92b8ff5d30821f0a515dc", "a664fb188d1bf1eaf54022f9cccd19f0977d91cb69d53bfcbf4e7bcb9949269f", 753.1895, 25.43575, 16.5325, 129.75975),
        Frozen("cur_rice_milk_banana", "d9b89beace47d5ee9afe4c76abd76e86f01cb087b1b9faff6154d10d14929984", "6020ce1f30a48431b4cc519f831d6f4f1765f19242ca9309bf0cd1edfb8805fa", 481.90825, 13.3887525, 8.89895, 89.9415475),
        Frozen("cur_broccoli_pepper_eggs", "bfc2af2037e62b9627fd531fddc87d2c4f106b8e1ccfd2afbdc8b06f970acd77", "0d30b615c14d95a0ff872d40ae4696dde3031d1e61f398ade2f289301be2e222", 308.53, 19.91, 20.194, 15.42)
    )

    private val rejected = setOf(
        "cur_yogurt_berries_oat",
        "cur_chickpea_salad",
        "cur_greek_salad",
        "cur_cod_potato_tray",
        "cur_salmon_broccoli_tray",
        "cur_cottage_banana_bowl",
        "cur_turkey_stuffed_peppers",
        "cur_salmon_potato_salad",
        "cur_lemon_chicken_rice",
        "cur_salmon_fishcakes",
        "cur_pork_buckwheat"
    )

    @Test fun allTwentyCandidatesHaveExactlyOneAuditedOutcome() {
        assertEquals(9, admitted.size)
        assertEquals(9, admitted.map { it.id }.toSet().size)
        assertEquals(11, rejected.size)
        assertEquals(20, admitted.size + rejected.size)
        assertTrue(admitted.none { it.id in rejected })
        assertEquals(9, M2PublishedMethodBulkThird20261025.reviews.size)
        assertEquals(66, M2PublishedMethodReviews.reviews.size)
        for (id in rejected) {
            assertFalse("Rejected ID is not admitted: $id",
                M2PublishedMethodReviews.reviews.containsKey(id))
            val recipe = OfflineRecipes.curatedDrafts.single { it.id == id }
            assertFalse(RecipeEvidenceAudit.inspect(recipe).documentedReady)
        }
    }

    @Test fun independentlyFrozenSourceFingerprintsAndNutritionMatchRealDrafts() {
        for (expected in admitted) {
            val recipe = OfflineRecipes.curatedDrafts.single { it.id == expected.id }
            val review = M2PublishedMethodReviews.reviews.getValue(expected.id)
            assertEquals(expected.recipeSha, RecipeEvidenceAudit.fingerprint(recipe))
            assertEquals(expected.recipeSha, review.recipeFingerprintSha256)
            assertEquals(expected.excerptSha, review.methodSnapshotSha256)
            assertEquals(expected.excerptSha, RecipeEvidenceAudit.sha256Utf8(
                requireNotNull(review.methodSnapshotText)))
            assertTrue(review.publishedMethodSource.startsWith("https://"))
            assertEquals(RecipeNutritionBasis.RAW_EDIBLE_INPUT_ESTIMATE, review.nutritionBasis)
            val recorded = requireNotNull(review.independentlyRecalculatedRawNutrition)
            val actual = OfflineRecipes.nutrition(recipe)
            for ((name, expectedValue, recordedValue, computedValue) in listOf(
                listOf("kcal", expected.kcal, recorded.kcal, actual.kcal),
                listOf("protein", expected.protein, recorded.protein, actual.protein),
                listOf("fat", expected.fat, recorded.fat, actual.fat),
                listOf("carbs", expected.carbs, recorded.carbs, actual.carbs)
            ).map { Quarter(it[0] as String, it[1] as Double,
                it[2] as Double, it[3] as Double) }) {
                assertEquals("${expected.id} frozen $name", expectedValue, recordedValue, 0.000001)
                assertEquals("${expected.id} computed $name", expectedValue, computedValue, 0.00001)
            }
            val audit = RecipeEvidenceAudit.inspect(recipe, review)
            assertTrue("${expected.id}: ${audit.issues}", audit.documentedReady)
            assertFalse(audit.skuLabelCleared)
            assertFalse(audit.physicalTrialDocumented)
            assertTrue(RecipeAuditNotice.FINISHED_YIELD_UNKNOWN in audit.notices)
        }
    }

    private data class Quarter(val name: String, val expected: Double,
        val recorded: Double, val computed: Double)

    @Test fun tamperingWithEverySourceRecipeOrCalculationRevokesAdmission() {
        for (f in admitted) {
            val recipe = OfflineRecipes.curatedDrafts.single { it.id == f.id }
            val review = M2PublishedMethodReviews.reviews.getValue(f.id)
            val editedExcerpt = review.copy(methodSnapshotText =
                requireNotNull(review.methodSnapshotText) + " corrupted")
            assertTrue(RecipeAuditIssue.METHOD_SNAPSHOT_MISMATCHED in
                RecipeEvidenceAudit.inspect(recipe, editedExcerpt).issues)
            val changed = recipe.copy(ingredients =
                recipe.ingredients.mapIndexed { i, v ->
                    if (i == 0) v.copy(grams = v.grams + 1) else v
                })
            assertTrue(RecipeAuditIssue.DOCUMENTARY_REVIEW_STALE in
                RecipeEvidenceAudit.inspect(changed, review).issues)
            val macros = requireNotNull(review.independentlyRecalculatedRawNutrition)
            val falseNutrition = review.copy(independentlyRecalculatedRawNutrition =
                macros.copy(protein = macros.protein + 2.0))
            assertTrue(RecipeAuditIssue.NUTRITION_RECALCULATION_MISMATCHED in
                RecipeEvidenceAudit.inspect(recipe, falseNutrition).issues)
            assertFalse(RecipeEvidenceAudit.inspect(recipe, falseNutrition).documentedReady)
        }
    }

    @Test fun aggregateM2GateRemainsOpenWith102UnauditedAuthorMethods() {
        val r = RecipeEvidenceAudit.report()
        assertEquals(150, r.distinctDrafts)
        assertEquals(200, r.generatedTemplates)
        assertEquals(66, r.documentedReviewed)
        assertEquals(84, OfflineRecipes.curatedDrafts.count {
            it.id !in M2PublishedMethodReviews.reviews
        })
        assertEquals(0, r.skuLabelsClearedByRecipes)
        assertFalse(r.meetsM2Gate)
    }
}
